from pysat.solvers import Glucose3

# This is the pigeonhole problem: 5 pigeons, 4 holes
# Each pigeon must be assigned to exactly one hole
# Each hole can contain at most one pigeon

# Variables: x_{i,j} means pigeon i is in hole j
# i ranges from 0 to 4 (5 pigeons)
# j ranges from 0 to 3 (4 holes)

def var(i, j):
    return i * 4 + j + 1  # 1-indexed for SAT solver

solver = Glucose3()

# Each pigeon must be assigned to exactly one hole
for i in range(5):
    # At least one hole
    clause = [var(i, j) for j in range(4)]
    solver.add_clause(clause)
    # At most one hole (pairwise)
    for j1 in range(4):
        for j2 in range(j1+1, 4):
            solver.add_clause([-var(i, j1), -var(i, j2)])

# Each hole can contain at most one pigeon
for j in range(4):
    for i1 in range(5):
        for i2 in range(i1+1, 5):
            solver.add_clause([-var(i1, j), -var(i2, j)])

if solver.solve():
    model = solver.get_model()
    print("SAT")
    solution = []
    for i in range(5):
        for j in range(4):
            if model[var(i, j)-1] > 0:
                solution.append(j)
                break
    print(solution)
else:
    print("UNSAT")

solver.delete()
